CREATE POLICY "Allow prospects to view and edit their own application" ON public.people FOR ALL TO authenticated USING ((application_id = current_setting('app.application_id', true)::text AND application_token = current_setting('app.application_token', true)::text AND application_token_exp > now())) WITH CHECK ((application_id = current_setting('app.application_id', true)::text AND application_token = current_setting('app.application_token', true)::text AND application_token_exp > now()));
